--
-- Table structure for table `attendance_declarations`
--

DROP TABLE IF EXISTS `attendance_declarations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendance_declarations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `date` date NOT NULL,
  `status` varchar(255) NOT NULL,
  `validation_status` varchar(255) NOT NULL DEFAULT 'EN_ATTENTE',
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `manager_validated_by` bigint(20) unsigned DEFAULT NULL,
  `manager_validated_at` timestamp NULL DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_declarations_user_id_date_unique` (`user_id`,`date`),
  KEY `attendance_declarations_validated_by_foreign` (`validated_by`),
  KEY `attendance_declarations_company_id_user_id_date_index` (`company_id`,`user_id`,`date`),
  KEY `attendance_declarations_company_id_validation_status_index` (`company_id`,`validation_status`),
  KEY `attendance_declarations_manager_validated_by_foreign` (`manager_validated_by`),
  CONSTRAINT `attendance_declarations_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendance_declarations_manager_validated_by_foreign` FOREIGN KEY (`manager_validated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `attendance_declarations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendance_declarations_validated_by_foreign` FOREIGN KEY (`validated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=237 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
